    {
      "claim": "pDebounce.promise with after=true fails to propagate rejections from the initial execution to concurrent callers, causing them to hang indefinitely instead of rejecting.",
      "path": "index.js",
      "start_line": 90,
      "end_line": 151,
      "evidence": "if (!options.after) { return currentPromise; } ... return new Promise((resolve, reject) => { queuedCall.resolvers.push({resolve, reject}); });",
      "reproduction": {
        "code": "const pDebounce = (await load('./index.js')).default;\nconst fn = pDebounce.promise(async () => { throw new Error('fail'); }, { after: true });\nconst p1 = fn();\nconst p2 = fn();\ntry { await p1; assert.fail('should reject'); } catch (e) { assert.ok(e.message === 'fail'); }\ntry { await p2; assert.fail('should reject'); } catch (e) { assert.ok(e.message === 'fail'); }"
      }
    }
  ]
}
